import React, { useState, useEffect } from 'react';
import './Following.css';

const Following = () => {
  const [isTracking, setIsTracking] = useState(false);
  const [followers, setFollowers] = useState([]);
  const [shareCode, setShareCode] = useState('');

  useEffect(() => {
    generateShareCode();
    loadFollowers();
  }, []);

  const generateShareCode = () => {
    const code = Math.random().toString(36).substring(2, 8).toUpperCase();
    setShareCode(code);
  };

  const loadFollowers = () => {
    const saved = localStorage.getItem('safehaven_followers');
    if (saved) {
      setFollowers(JSON.parse(saved));
    }
  };

  const toggleTracking = () => {
    setIsTracking(!isTracking);
  };

  const addFollower = () => {
    const name = prompt('Enter follower name:');
    const phone = prompt('Enter follower phone:');
    if (name && phone) {
      const newFollower = { id: Date.now(), name, phone, active: true };
      const updated = [...followers, newFollower];
      setFollowers(updated);
      localStorage.setItem('safehaven_followers', JSON.stringify(updated));
    }
  };

  const removeFollower = (id) => {
    const updated = followers.filter(f => f.id !== id);
    setFollowers(updated);
    localStorage.setItem('safehaven_followers', JSON.stringify(updated));
  };

  return (
    <div className="following-container">
      <h2>Following & Tracking</h2>

      <div className="tracking-status">
        <button 
          className={`tracking-btn ${isTracking ? 'active' : ''}`}
          onClick={toggleTracking}
        >
          {isTracking ? '🟢 Tracking Active' : '🔴 Start Tracking'}
        </button>
      </div>

      <div className="share-section">
        <h3>Share Your Location</h3>
        <div className="share-code">
          <span>Share Code: <strong>{shareCode}</strong></span>
          <button onClick={generateShareCode}>🔄</button>
        </div>
      </div>

      <div className="followers-section">
        <h3>Followers ({followers.length})</h3>
        <button className="add-follower-btn" onClick={addFollower}>
          + Add Follower
        </button>

        <div className="followers-list">
          {followers.map(follower => (
            <div key={follower.id} className="follower-item">
              <span>{follower.name} - {follower.phone}</span>
              <button onClick={() => removeFollower(follower.id)}>❌</button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Following;
